func build(limit: int) -> Result[int, int]:
    mut total = 0
    mut values: int[] = []
    for index in range(limit):
        values.append(index)
    if limit > 3:
        return Err(len(values))
    total = len(values)
    return Ok(total)

func chain(limit: int) -> Result[int, int]:
    mut answer = 0
    mut noise: int[] = [limit]
    const built = try build(limit)
    answer = built + len(noise)
    return Ok(answer * 2)

